  ```csharp
  public async Task<List<BranchDto>> GetBranchesCachedAsync()
  {
      return await _memoryCache.GetOrCreateAsync("CACHE_KEY_BRANCHES", async entry =>
      {
          entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15);
          return await _repository.Query().ProjectTo<BranchDto>(_mapper.ConfigurationProvider).ToListAsync();
